// ============================================================
// CLASS 2 SUBJECT MODULE ADAPTER
// Golden learning engine above is from standalone Toán 2.
// Account/session/Admin/backend shell are NOT inherited from standalone.
// ============================================================
let mathModuleCtx_ = null;
let mathModuleRoot_ = null;
let mathModuleMounted_ = false;
let mathModuleDestroyed_ = false;
let mathModuleLastTab_ = '';
let mathScoreObserver_ = null;
let mathUiObserver_ = null;
let mathUiNormalizeRaf_ = 0;
let mathModuleAudioPrimed_ = false;
const MATH_MODULE_STYLE_ID_ = 'class2-math-standalone-style';
const MATH_MODULE_RUNTIME_ID_ = 'class2-math-runtime';
const MATH_DEPENDENCY_MARK_ = 'class2-math-dependency';
const mathModulePreviousGlobals_ = new Map();

async function class2MathApiRequest_(action, payload = {}, options = {}) {
    if (!mathModuleCtx_?.isAuthenticated) {
        const err = new Error('AUTH_REQUIRED'); err.code = 'AUTH_REQUIRED'; throw err;
    }
    return mathModuleCtx_.apiRequest(action, payload, options);
}

function syncClass2MathUser_() {
    const u = mathModuleCtx_?.user || null;
    const access = String(mathModuleCtx_?.accessType || 'regular').toLowerCase();
    class2ModuleAccessType_ = access;
    currentUser = u ? {
        maHS: String(u.userId || ''),
        hoTen: String(u.name || ''),
        role: String(u.role || 'student'),
        vaiTro: String(u.role || 'student'),
        accountType: access,
        loaiTaiKhoan: access,
        isGuest: false
    } : {
        maHS: '', hoTen: 'Bé', role: 'student', vaiTro: 'student',
        accountType: 'regular', loaiTaiKhoan: 'regular', isGuest: true
    };
    try { refreshAccessUI(); } catch (_) {}
}

let class2ModuleAccessType_ = 'regular';
function isAdminUser() { return String(mathModuleCtx_?.user?.role || '').toLowerCase() === 'admin'; }
function hasPremiumAccess() {
    if (isAdminUser()) return true;
    return ['trial','vip'].includes(String(class2ModuleAccessType_ || mathModuleCtx_?.accessType || 'regular').toLowerCase());
}
function isPremiumUser() { return hasPremiumAccess(); }
function openAuthFromGuest(tab = 'login') { mathModuleCtx_?.openAuth?.(tab === 'register' ? 'register' : 'login'); }
function showPremiumAccessModal(featureName = 'Nội dung này') {
    if (typeof mathModuleCtx_?.requestPremiumAccess === 'function') {
        mathModuleCtx_.requestPremiumAccess(featureName);
        return false;
    }
    const modalId = 'class2-math-premium-access-modal';
    let modal = document.getElementById(modalId);
    if (!modal) {
        modal = document.createElement('div');
        modal.id = modalId;
        modal.className = 'hidden fixed inset-0 z-[90] bg-slate-900/55 backdrop-blur-sm flex items-center justify-center p-4';
        (mathModuleRoot_ || document.body).appendChild(modal);
    }
    const guest = !currentUser || currentUser.isGuest;
    const tier = String(class2ModuleAccessType_ || 'regular').toLowerCase();
    modal.innerHTML = `<div class="w-full max-w-[350px] bg-[#fffdf4] rounded-[26px] border-2 border-amber-300 shadow-2xl overflow-hidden"><div class="px-5 pt-5 pb-4 text-center"><div class="mx-auto w-[70px] h-[70px] rounded-full bg-white border border-amber-300 flex items-center justify-center text-[38px] shadow-sm mb-3">🐰</div><h3 class="text-[17px] font-black text-orange-600 mb-2.5">${escapeHtml(featureName)}</h3><div class="text-[13px] leading-[1.7] font-extrabold text-slate-700">${guest ? `Đây là ${escapeHtml(featureName)} dành cho tài khoản Trial hoặc VIP của môn Toán.<br>Con đăng nhập bằng tài khoản Lớp 2 để tiếp tục nhé!<br>Nội dung Free trong Khám phá vẫn học bình thường.` : `Quyền Toán hiện tại của con là <span class="text-orange-600">${escapeHtml(tier === 'regular' ? 'Regular' : tier.toUpperCase())}</span>.<br>${escapeHtml(featureName)} dành cho tài khoản Trial hoặc VIP của môn Toán.<br>Nội dung Free trong Khám phá vẫn học bình thường.`}</div></div><div class="bg-white/80 border-t border-pink-100 px-3.5 py-3 space-y-2">${guest ? `<div class="grid grid-cols-2 gap-2"><button onclick="closePremiumAccessModal();openAuthFromGuest('login')" class="h-10 rounded-2xl bg-gradient-to-r from-amber-400 to-orange-400 text-white font-black text-sm shadow-sm">Đăng nhập</button><button onclick="closePremiumAccessModal();openAuthFromGuest('register')" class="h-10 rounded-2xl bg-white border border-fuchsia-300 text-fuchsia-500 font-black text-sm">Đăng ký</button></div>` : ''}<button onclick="closePremiumAccessModal()" class="w-full h-10 rounded-2xl bg-slate-100 hover:bg-slate-200 text-slate-500 text-sm font-black">Để sau nhé</button></div></div>`;
    modal.classList.remove('hidden');
    return false;
}
function closePremiumAccessModal() {
    document.getElementById('class2-math-premium-access-modal')?.classList.add('hidden');
    document.getElementById('premium-access-modal')?.classList.add('hidden');
}
function requirePremium(featureName) {
    if (hasPremiumAccess()) return true;
    showPremiumAccessModal(featureName);
    return false;
}

function showAppNotice(message, options = {}) {
    if (mathModuleCtx_?.hooks?.showDialog) {
        mathModuleCtx_.hooks.showDialog({
            title: options.title || (String(message).includes('🎉') ? 'Giỏi lắm!' : 'Cô Thỏ Ngọc nhắn bé'),
            message: String(message ?? ''),
            icon: options.icon || (String(message).includes('🎉') ? '🎉' : '🐰'),
            primaryLabel: options.okText || 'Đã hiểu',
            onPrimary: typeof options.onClose === 'function' ? options.onClose : undefined
        });
        return;
    }
    mathModuleCtx_?.hooks?.showToast?.(String(message ?? ''));
}
function showAppConfirm(message, onConfirm, options = {}) {
    if (mathModuleCtx_?.hooks?.showDialog) {
        mathModuleCtx_.hooks.showDialog({
            title: options.title || 'Xác nhận nộp bài',
            message: String(message ?? ''),
            icon: options.icon || '📝',
            primaryLabel: options.confirmText || 'Đồng ý',
            onPrimary: typeof onConfirm === 'function' ? onConfirm : undefined,
            secondaryLabel: options.cancelText || 'Làm tiếp'
        });
        return;
    }
    if (typeof onConfirm === 'function') onConfirm();
}


async function loadSharedImageCatalog_() {
    if (sharedImageCatalogCache_) return sharedImageCatalogCache_;
    const res = await fetch(SHARED_IMAGE_CATALOG_FILE, {cache:'no-store'});
    if (!res.ok) throw new Error('Không tải được catalog ảnh dùng chung.');
    sharedImageCatalogCache_ = await res.json();
    return sharedImageCatalogCache_;
}
function class2MathImageSrc_(imageId) {
    const images = sharedImageCatalogCache_?.images || {};
    const meta = images && typeof images === 'object' ? images[String(imageId || '')] : null;
    return meta && typeof meta.src === 'string' ? meta.src : '';
}
function applyClass2MathSceneImageVars_() {
    if (!mathModuleRoot_) return;
    const cssUrl = (src) => `url(\"${String(src || '').replace(/\\/g,'\\\\').replace(/\"/g,'\\\"')}\")`;
    const bridge = class2MathImageSrc_('number_bridge_river');
    const train = class2MathImageSrc_('number_train_valley');
    if (bridge) mathModuleRoot_.style.setProperty('--nb-scene-image', cssUrl(bridge));
    if (train) mathModuleRoot_.style.setProperty('--nt-scene-image', cssUrl(train));
}

async function fetchExerciseQuestionsFlat_() {
    if (exerciseQuestionsFlatCache_) return exerciseQuestionsFlatCache_;
    const files = [BAI_TAP_HK1_DATA_FILE, BAI_TAP_HK2_DATA_FILE];
    const data = await Promise.all(files.map(async (file) => {
        const res = await fetch(`${file}?v=${DATA_VERSION}`, {cache:'no-store'});
        if (!res.ok) throw new Error(`Không thể tải file dữ liệu ${file}`);
        return res.json();
    }));
    const raw = data.flatMap(d => Array.isArray(d) ? d : (Array.isArray(d?.questions) ? d.questions : []));
    exerciseQuestionsFlatCache_ = raw.map(normalizeQuestion).filter(Boolean);
    return exerciseQuestionsFlatCache_;
}
async function fetchReviewQuestionsFlat_() {
    if (reviewQuestionsFlatCache_) return reviewQuestionsFlatCache_;
    const res = await fetch(`${ON_TAP_DATA_FILE}?v=${REVIEW_DATA_VERSION}`, {cache:'no-store'});
    if (!res.ok) throw new Error('Không thể tải dữ liệu Ôn tập Toán 2');
    const data = await res.json();
    const raw = Array.isArray(data) ? data : (Array.isArray(data?.questions) ? data.questions : []);
    reviewQuestionsFlatCache_ = raw.map(normalizeQuestion).filter(Boolean);
    return reviewQuestionsFlatCache_;
}

function getQuestionsForBaiTapToan2_(bt) {
    if (!bt || !exerciseQuestionsFlatCache_) return [];
    const lessonId = String(bt.lesson_id || '').trim();
    const subIds = (bt.sub_ids || []).map(String);
    let scoped = lessonId
        ? exerciseQuestionsFlatCache_.filter(q => Array.isArray(q.lesson_refs) && q.lesson_refs.includes(lessonId))
        : [];
    if (!scoped.length) scoped = exerciseQuestionsFlatCache_.filter(q => subIds.length && subIds.includes(String(q.sub_id || q.sub_topic || '')));
    if (!scoped.length) return [];
    const candidateTarget = Math.max(20, Number(bt.candidate_pool_target || 30));
    const candidate = shuffleArray(scoped).slice(0, Math.min(candidateTarget, scoped.length));
    const by = {};
    candidate.forEach(q => {
        const m = String(q.skill_tag || q.tag || '').match(/C([1-6])/i);
        const k = m ? `C${m[1]}` : '_UNTAGGED';
        (by[k] ||= []).push(q);
    });
    const out = [], used = new Set();
    let go = true;
    while (out.length < 20 && go) {
        go = false;
        for (const k of ['C1','C2','C3','C4','C5','C6','_UNTAGGED']) {
            const a = by[k] || [];
            while (a.length && used.has(a[0].question_id)) a.shift();
            if (a.length && out.length < 20) { const q = a.shift(); used.add(q.question_id); out.push(q); go = true; }
        }
    }
    for (const q of candidate) {
        if (out.length >= 20) break;
        if (!used.has(q.question_id)) { used.add(q.question_id); out.push(q); }
    }
    return shuffleArray(out.slice(0,20));
}
async function selectBaiTapToan2_(bai) {
    if (!requirePremium('Bài tập')) return;
    stopSpeaking();
    showLoadingOverlay(`Đang chuẩn bị Bài tập ${bai}...`);
    try {
        const data = await loadBaiHocData();
        const bt = (data?.bai_tap || []).find(x => Number(x.bai) === Number(bai));
        if (!bt) throw new Error('Không tìm thấy Bài tập');
        if (!isBaiTapUnlockedToan2_(data, bai)) { showLockedBaiTapToan2_(bai); return; }
        await fetchExerciseQuestionsFlat_();
        const qs = getQuestionsForBaiTapToan2_(bt);
        if (qs.length < 20) throw new Error(`Kho câu hỏi phù hợp hiện chỉ có ${qs.length} câu; cần tối thiểu 20 câu.`);
        activeRoadmapContext = { week:Number(bai), bai:Number(bai), semester:Number(bt.semester || 1), exerciseId:String(bt.exercise_id || bt.lesson_id || `BT${bai}`), topicId:`BT${bai}`, chuDe:`Bài tập ${bai} · ${bt.title||''}` };
        pendingTopicQuiz = null; activeExamContext = null;
        updateNavTabs('Bài tập', '✏️', `Bài ${bai}`, bt.title || '');
        startTopicQuiz(bai, activeRoadmapContext.chuDe, qs, null);
    } catch (err) { showAppNotice(`Không thể mở Bài tập: ${err.message}`); }
    finally { hideLoadingOverlay(); }
}
async function openReviewHubFromQuestionBank() {
    setAppShellRootMode_(true);
    stopSpeaking();
    setMainTabActive_('review');
    activeTopicId = 'review'; activeExamContext = null; activeRoadmapContext = null;
    updateNavTabs('Ôn tập', '📚', null);
    showLoadingOverlay('Đang tải nội dung Ôn tập...');
    try {
        const reviewQuestions = await fetchReviewQuestionsFlat_();
        hideLoadingOverlay();
        if (!reviewQuestions.length) throw new Error('Chưa có câu hỏi Ôn tập');
        renderExploreSubtopics('review', 'Ôn tập', { questions: reviewQuestions });
        setMainTabActive_('review');
    } catch (err) {
        hideLoadingOverlay(); showAppNotice(`Không thể tải Ôn tập: ${err.message}`);
    }
}

function class2LearningEvents_() {
    return (quizAnsweredLog || []).slice(-20).map((item, idx) => ({
        t: Date.now() - ((quizAnsweredLog.length - idx) * 5),
        q: String(item.question_id || item.id || `q${idx+1}`).slice(0,120),
        s: /^TOAN_C[1-6]$/.test(String(item.skill_tag || item.tag || '').toUpperCase()) ? String(item.skill_tag || item.tag).toUpperCase() : '',
        o: item.isCorrect ? 'correct' : 'wrong',
        e: activeExamContext ? 'exam' : activeRoadmapContext ? 'exercise' : 'practice',
        u: 0,
        l: Number(item.level || item.difficulty || 0) || 0,
        tp: String(activeRoadmapContext?.topicId || activeExamContext?.examId || activeTopicId || '').slice(0,80)
    }));
}
async function saveLearningTelemetry_() {
    if (!mathModuleCtx_?.isAuthenticated) return;
    const events = class2LearningEvents_();
    if (!events.length) return;
    try { await class2MathApiRequest_('learningProfileSaveBatch', {subjectId:'toan', events}); } catch (_) {}
}

// Official Toán 2 assessment: client only submits raw answers.
// Server verifies canonical answers, sequence and the >=80% unlock rule.
function class2AssessmentAnswers_() {
    return (activeQuestionsList || []).map((q, idx) => ({
        questionId: String(q?.question_id ?? q?.id ?? ''),
        answer: userAnswers[idx] === undefined ? '' : String(userAnswers[idx])
    }));
}
function class2AssessmentDurationMs_() {
    return quizStartTime ? Math.max(0, Date.now() - quizStartTime) : 0;
}
async function saveExamResultToSheet() {
    await saveLearningTelemetry_();
    if (!mathModuleCtx_?.isAuthenticated || !activeExamContext) return;

    // HSG is a separate score_only branch: do not mix it into official HK1/HK2 C1-C6 history.
    if (activeExamContext.categoryKey === 'hsg' || String(activeExamContext.examId || '').startsWith('12.3.')) return;

    const semester = activeExamContext.categoryKey === 'hocky2' ? 'hk2' : 'hk1';
    try {
        const result = await class2MathApiRequest_('assessmentAttemptSubmit', {
            subjectId:'toan',
            kind:'baithi',
            semester,
            examId:String(activeExamContext.examId || ''),
            answers:class2AssessmentAnswers_(),
            durationMs:class2AssessmentDurationMs_()
        });
        const scoreEl = document.getElementById('report-total-score-val');
        const ratioEl = document.getElementById('report-correct-ratio-val');
        if (scoreEl && Number.isFinite(Number(result?.score))) scoreEl.textContent = Number(result.score).toFixed(1);
        if (ratioEl && Number.isFinite(Number(result?.correct)) && Number.isFinite(Number(result?.total))) ratioEl.textContent = `${Number(result.correct)}/${Number(result.total)}`;
    } catch (err) {
        showAppNotice('Kết quả trên màn hình vẫn giữ để bé xem, nhưng chưa đồng bộ được lịch sử chính thức. Bé thử lại khi mạng ổn định nhé!', {title:'Chưa đồng bộ',icon:'📡'});
    }
}
async function saveWeeklyProgressToSheet(percent, starCount, scoreVal) {
    await saveLearningTelemetry_();
    if (!mathModuleCtx_?.isAuthenticated || !activeRoadmapContext) return;
    const baiSo = Number(activeRoadmapContext.bai || activeRoadmapContext.week || 0);
    const semester = Number(activeRoadmapContext.semester || (baiSo <= 22 ? 1 : 2)) === 2 ? 'hk2' : 'hk1';
    try {
        const before = getUnlockedBaiTapToan2_();
        const result = await class2MathApiRequest_('assessmentAttemptSubmit', {
            subjectId:'toan',
            kind:'baitap',
            semester,
            baiSo,
            answers:class2AssessmentAnswers_(),
            durationMs:class2AssessmentDurationMs_()
        });
        const progress = result?.progress || {};
        class2ExerciseUnlockedIndex_ = Math.max(1, Number(progress.unlockedIndex || before || 1));
        class2ExerciseProgressLoaded_ = true;

        const officialPercent = Number(result?.percent);
        const officialCorrect = Number(result?.correct);
        const officialTotal = Number(result?.total);
        const scoreEl = document.getElementById('report-total-score-val');
        const ratioEl = document.getElementById('report-correct-ratio-val');
        if (scoreEl && Number.isFinite(officialPercent)) scoreEl.textContent = (officialPercent / 10).toFixed(1);
        if (ratioEl && Number.isFinite(officialCorrect) && Number.isFinite(officialTotal)) ratioEl.textContent = `${officialCorrect}/${officialTotal}`;

        if (result?.passed && class2ExerciseUnlockedIndex_ > before) {
            const nextBai = class2ExerciseUnlockedIndex_;
            setTimeout(() => showAppNotice(`🎉 Máy chủ đã xác nhận bé đạt ${officialPercent}%! Bài tập ${nextBai} đã được mở khóa.`), 400);
        }
    } catch (err) {
        // Fail closed: never unlock from the client-computed percent.
        await refreshClass2ExerciseProgress_();
        showAppNotice('Bài làm chưa được máy chủ xác nhận nên chưa mở khóa bài tiếp theo. Bé thử lại khi mạng ổn định nhé!', {title:'Chưa xác nhận tiến trình',icon:'🔒'});
    }
}

function normalizeClass2AssessmentHistoryRow_(row, kind) {
    const out = {...row};
    out.Timestamp = row.Timestamp || row.timestamp || '';
    out.ngayLam = out.Timestamp;
    out.thoiGianLamBai = row.ThoiGianLamBai || row.thoiGianLamBai || '';
    out.tongCauHoi = Number(row.TongCauHoi ?? row.tongCauHoi ?? 0);
    out.soCauDung = Number(row.SoCauDung ?? row.soCauDung ?? 0);
    ['C1','C2','C3','C4','C5','C6'].forEach(k => {
        const correct = Number(row[k+'_Dung'] || 0);
        const total = Number(row[k+'_Tong'] || 0);
        out[k+'_Dung'] = correct;
        out[k+'_Tong'] = total;
        const taxo = SKILL_TAXONOMY[k];
        if (kind === 'baitap') {
            out[taxo.sheetCol] = correct;
            out[taxo.totalCol] = total;
        } else {
            const pointsEarnedRaw = row[k+'_Diem'];
            const pointsTotalRaw = row[k+'_DiemTong'];
            const pointsEarned = pointsEarnedRaw === '' || pointsEarnedRaw == null ? (total ? correct : '') : Number(pointsEarnedRaw);
            const pointsTotal = pointsTotalRaw === '' || pointsTotalRaw == null ? (total || '') : Number(pointsTotalRaw);
            out[`diem${k}`] = pointsEarned;
            out[taxo.sheetCol] = pointsEarned;
            out[taxo.totalCol] = pointsTotal;
            out[`soCau${k}`] = total || '';
        }
    });
    if (kind === 'baitap') {
        out.tuan = Number(row.BaiSo || row.Tuan || 0);
        out.chuDe = row.BaiSo ? `Bài ${row.BaiSo}` : String(row.BaiId || row.ChuDe || 'Bài tập');
        out.percent = Number(row.PhanTram || row.Percent || 0);
        out.score = Number(row.DiemSo || row.Score || out.percent/10 || 0);
        out.tongDiem = out.score;
    } else {
        out.deSo = Number(row.DeSo || 0);
        out.score = Number(row.DiemSo || row.Score || 0);
        out.tongDiem = out.score;
        out.maxDiem = Number(row.TongDiem || 10);
    }
    return out;
}
async function fetchClass2AssessmentHistory_(sheetName) {
    if (sheetName === 'LichSuTienTrinhTuan') {
        const [a,b] = await Promise.all([
            class2MathApiRequest_('assessmentHistoryGet',{subjectId:'toan',kind:'baitap',semester:'hk1'}),
            class2MathApiRequest_('assessmentHistoryGet',{subjectId:'toan',kind:'baitap',semester:'hk2'})
        ]);
        return [...(a?.history||[]),...(b?.history||[])].map(r=>normalizeClass2AssessmentHistoryRow_(r,'baitap')).sort((x,y)=>new Date(y.Timestamp||0)-new Date(x.Timestamp||0));
    }
    if (sheetName === 'LichSuBaiThi_HK1' || sheetName === 'LichSuBaiThi_HK2') {
        const semester = sheetName.endsWith('HK2') ? 'hk2' : 'hk1';
        const data = await class2MathApiRequest_('assessmentHistoryGet',{subjectId:'toan',kind:'baithi',semester});
        return (data?.history||[]).map(r=>normalizeClass2AssessmentHistoryRow_(r,'baithi'));
    }
    return [];
}
async function openHistoryModal(sheetName = 'LichSuTienTrinhTuan') {
    if (!mathModuleCtx_?.isAuthenticated) {
        showAppNotice('Bé vui lòng đăng nhập bằng tài khoản Lớp 2 để xem lịch sử nhé!', {title:'Cần đăng nhập',icon:'🔐'});
        mathModuleCtx_?.openAuth?.('login');
        return;
    }
    const modal=document.getElementById('modal-history-progress'); if(!modal) return;
    modal.classList.remove('hidden');
    const name=document.getElementById('hist-info-name'); if(name) name.textContent=currentUser?.hoTen||'--';
    const code=document.getElementById('hist-info-code'); if(code) code.textContent=currentUser?.maHS||'--';
    const cls=document.getElementById('hist-info-class'); if(cls) cls.textContent='--';
    const dob=document.getElementById('hist-info-dob'); if(dob) dob.textContent='--';
    const date=document.getElementById('hist-report-date'); if(date) date.textContent=new Date().toLocaleDateString('vi-VN');
    const titleMap={LichSuTienTrinhTuan:'Báo cáo tiến trình Bài tập theo SGK',LichSuBaiThi_HK1:'Báo cáo kết quả đấu trường — Học kỳ 1',LichSuBaiThi_HK2:'Báo cáo kết quả đấu trường — Học kỳ 2',LichSuBaiThi_HSG:'Báo cáo kết quả đấu trường — Học sinh giỏi'};
    const title=document.getElementById('hist-modal-title'); if(title) title.textContent=titleMap[sheetName]||'Kết quả tiến trình học tập';
    if(sheetName==='LichSuBaiThi_HSG') { await renderHistoryReport([],sheetName); showAppNotice('Đề HSG không ghi vào báo cáo sáu năng lực chính thức.',{title:'Lịch sử HSG',icon:'🏆'}); return; }
    showLoadingOverlay('Đang trích xuất dữ liệu và vẽ biểu đồ năng lực...');
    try { const rows=await fetchClass2AssessmentHistory_(sheetName); hideLoadingOverlay(); await renderHistoryReport(rows,sheetName); }
    catch(_) { hideLoadingOverlay(); showAppNotice('Chưa tải được lịch sử từ tài khoản Lớp 2. Vui lòng thử lại.',{title:'Lịch sử học tập',icon:'📊'}); }
}

function ensureMathDependency_(kind, url, testFn) {
    if (typeof testFn === 'function' && testFn()) return Promise.resolve();
    const attr = `data-${MATH_DEPENDENCY_MARK_}`;
    const existing = document.querySelector(`[${attr}="${url}"]`);
    if (existing) return new Promise((resolve,reject)=>{ if(typeof testFn==='function'&&testFn()) return resolve(); existing.addEventListener('load',resolve,{once:true}); existing.addEventListener('error',reject,{once:true}); });
    return new Promise((resolve,reject)=>{
        const el = kind === 'style' ? document.createElement('link') : document.createElement('script');
        if(kind==='style'){ el.rel='stylesheet'; el.href=url; } else { el.src=url; el.async=true; }
        el.setAttribute(attr,url); el.onload=()=>resolve(); el.onerror=()=>reject(new Error(`DEPENDENCY_LOAD_FAILED:${url}`)); document.head.appendChild(el);
    });
}
async function ensureMathDependencies_() {
    const jobs=[
        ensureMathDependency_('style','https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css',()=>!!document.querySelector('link[href*="font-awesome"]')),
        ensureMathDependency_('script','https://cdn.jsdelivr.net/npm/chart.js',()=>typeof window.Chart!=='undefined'),
        ensureMathDependency_('script','https://cdn.jsdelivr.net/npm/canvas-confetti@1.5.1/dist/confetti.browser.min.js',()=>typeof window.confetti==='function'),
        ensureMathDependency_('script','https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js',()=>typeof window.html2pdf!=='undefined')
    ];
    await Promise.allSettled(jobs);
}


