function ensureMathStyles_() {
    if (document.getElementById(MATH_MODULE_STYLE_ID_)) return;
    const style=document.createElement('style'); style.id=MATH_MODULE_STYLE_ID_; style.textContent=MATH_MODULE_CSS_ + MATH_CLASS2_FORM_COMPACT_CSS_ + MATH_SHELL_BREADCRUMB_CSS_ + MATH_HUB_CARD_CSS_ + MATH_ONE_PX_BORDER_CSS_ + MATH_BRANCH_DETAIL_CSS_ + MATH_UI_FINAL_AUDIT_CSS_ + MATH_TOAN1_INTERACTION_UI_CSS_ + MATH_ANSWER_AUDIO_UI_CSS_ + MATH_CARRY_34_LAYOUT_CSS_ + MATH_OPERATION_TERMS_UI_CSS_ + MATH_EXPLORE_TA2_SCALE_CSS_ + MATH_FOLDER_TA2_HOVER_CSS_; document.head.appendChild(style);
}

function mathReadStandaloneBreadcrumb_() {
    const out = [];
    [2,3,4].forEach((level) => {
        const tab = document.getElementById(`header-level${level}-tab`);
        const title = document.getElementById(`header-level${level}-title`);
        if (!tab || !title || tab.classList.contains('hidden')) return;
        const text = String(title.textContent || '').trim();
        if (text) out.push({ level, title:text });
    });
    return out;
}
function mathBreadcrumbLevel2Action_() {
    stopSpeaking();
    clearInterval(quizTimerInterval);
    if (currentMainTab === 'discover') {
        if (Number(activeTopicId) === 12) return openMathLab();
        if (activeTopicId) return returnToTopicLecture();
        return goHome();
    }
    if (currentMainTab === 'lessons') return openBaiHocHub(activeBaiHocToan2_?.lesson?.semester || 1);
    if (currentMainTab === 'exercises') return openRoadmap(activeRoadmapContext?.semester || 1);
    if (currentMainTab === 'review') return openReviewHubFromQuestionBank();
    if (currentMainTab === 'exams') return openExamHub();
    if (currentMainTab === 'games') return openMiniGameHub();
    return goHome();
}
function mathBreadcrumbLevel3Action_() {
    // Breadcrumb cấp 3 phải quay về đúng tầng cấp 3 đang hiển thị,
    // không được nhảy lùi về cấp chủ đề (level 2).
    // Ví dụ Mục 1: "Phạm vi 100" -> danh sách Bài giảng/Ghép số/Ước lượng/Tìm số.
    // Mục 2/Math Lab cũng đã có routing riêng trong returnToLevel3FromHeader().
    if (currentMainTab !== 'discover' || !activeTopicId) return;
    return returnToLevel3FromHeader();
}
function resetClass2MathBreadcrumb_() {
    const pill = document.getElementById('sub-pill');
    if (!pill) return;
    pill.classList.remove('math-sub-breadcrumbs');
    pill.removeAttribute('aria-label');
    pill.removeAttribute('title');
}
function syncClass2BannerFromMath_() {
    if (!mathModuleCtx_?.hooks) return;
    if (appShellRootMode_) {
        mathModuleCtx_.hooks.clearDetail?.();
        resetClass2MathBreadcrumb_();
        return;
    }
    const crumbs = mathReadStandaloneBreadcrumb_();
    const fallback = crumbs.map(x => x.title).join(' · ') || 'Toán 2';
    mathModuleCtx_.hooks.setDetail?.(fallback);
    const pill = document.getElementById('sub-pill');
    if (!pill) return;
    pill.classList.add('math-sub-breadcrumbs');
    pill.setAttribute('aria-label', 'Điều hướng chuyên mục Toán');
    pill.title = fallback;
    if (!crumbs.length) { pill.textContent = fallback; return; }
    pill.replaceChildren();
    crumbs.forEach((crumb, index) => {
        if (index) {
            const sep = document.createElement('span');
            sep.className = 'math-breadcrumb-sep';
            sep.setAttribute('aria-hidden','true');
            sep.textContent = '›';
            pill.appendChild(sep);
        }
        const clickable = crumb.level === 2 || (crumb.level === 3 && currentMainTab === 'discover' && !!activeTopicId);
        const node = document.createElement(clickable ? 'button' : 'span');
        if (clickable) node.type = 'button';
        node.className = `math-breadcrumb-tab math-breadcrumb-level${crumb.level}`;
        node.textContent = crumb.title;
        node.title = crumb.title;
        if (clickable) {
            node.setAttribute('aria-label', `Quay lại ${crumb.title}`);
            node.addEventListener('click', crumb.level === 2 ? mathBreadcrumbLevel2Action_ : mathBreadcrumbLevel3Action_);
        }
        pill.appendChild(node);
    });
}
const __mathStandaloneUpdateNavTabs_ = updateNavTabs;
updateNavTabs = function(level2Title, level2Icon, level3Title, level4Title) {
    const result = __mathStandaloneUpdateNavTabs_.apply(this, arguments);
    syncClass2BannerFromMath_();
    return result;
};
const __mathStandaloneSetAppShellRootMode_ = setAppShellRootMode_;
setAppShellRootMode_ = function(isRoot) {
    const result = __mathStandaloneSetAppShellRootMode_.apply(this, arguments);
    syncClass2BannerFromMath_();
    return result;
};

function primeMathAudio_() {
    if (mathModuleAudioPrimed_) return; mathModuleAudioPrimed_=true;
    const once=()=>{ try { const AC=window.AudioContext||window.webkitAudioContext; if(!audioCtx&&AC) audioCtx=new AC(); if(audioCtx?.state==='suspended') audioCtx.resume(); } catch(_){} };
    mathModuleRoot_?.addEventListener('pointerdown',once,{once:true,passive:true});
}
function syncMathScore_() { mathModuleCtx_?.hooks?.setScore?.(Number(starGreenCount||0),Number(starRedCount||0)); }
function installScoreObserver_() {
    mathScoreObserver_?.disconnect?.();
    const a=document.getElementById('star-green-count'), b=document.getElementById('star-red-count');
    if(!a||!b) return;
    mathScoreObserver_=new MutationObserver(syncMathScore_); mathScoreObserver_.observe(a,{childList:true,characterData:true,subtree:true}); mathScoreObserver_.observe(b,{childList:true,characterData:true,subtree:true}); syncMathScore_();
}



