const MATH_LISTEN_BUTTON_SELECTOR_ = [
    'button[onclick*="speak"]',
    'button[onclick*="Speak"]',
    'button[title*="Nghe"]',
    'button[aria-label*="Nghe"]',
    'button[data-nt-action="speak"]'
].join(',');

function normalizeMathAnswerPalette_() {
    if (!mathModuleRoot_) return;

    const applyGroup = (group) => {
        const items = group.filter((btn) => btn instanceof HTMLElement);
        if (!items.length) return;
        const signOnly = items.length === 3 && items.every((btn) => {
            const raw = String(btn.dataset.opt || btn.textContent || '').trim();
            return raw === '<' || raw === '>' || raw === '=';
        });
        items.forEach((btn, index) => {
            btn.dataset.mathAnswerTone = String((index % 4) + 1);
            btn.classList.toggle('math-standard-answer', !signOnly);
            btn.classList.toggle('math-sign-answer', signOnly);
        });
    };

    // Cau hoi chinh chi co mot nhom dap an tai mot thoi diem: gan mau truc tiep
    // theo thu tu de khong phu thuoc cau truc wrapper cua tung renderer.
    applyGroup(Array.from(mathModuleRoot_.querySelectorAll('#question-box .option-btn')));

    // Cac engine con co the co nhieu nhom choice, nen gom theo parent.
    ['.ml-choice', '.bh-choice', '.ns-choice'].forEach((selector) => {
        const groups = new Map();
        mathModuleRoot_.querySelectorAll(selector).forEach((btn) => {
            if (!(btn instanceof HTMLElement) || !btn.parentElement) return;
            const parent = btn.parentElement;
            if (!groups.has(parent)) groups.set(parent, []);
            groups.get(parent).push(btn);
        });
        groups.forEach(applyGroup);
    });
}

function normalizeMathListenButtons_() {
    if (!mathModuleRoot_) return;
    mathModuleRoot_.querySelectorAll(MATH_LISTEN_BUTTON_SELECTOR_).forEach((btn) => {
        if (!(btn instanceof HTMLButtonElement)) return;
        btn.classList.add('math-listen-button');
        btn.setAttribute('title', 'Nghe cô đọc');
        btn.setAttribute('aria-label', 'Nghe cô đọc');
        if (btn.dataset.mathListenNormalized === '1') return;
        btn.dataset.mathListenNormalized = '1';
        btn.replaceChildren();
        const icon = document.createElement('i');
        icon.className = 'fa-solid fa-volume-high';
        icon.setAttribute('aria-hidden', 'true');
        const label = document.createElement('span');
        label.textContent = 'Nghe cô đọc';
        btn.append(icon, label);
    });
}

function normalizeMathUi_() {
    normalizeMathAnswerPalette_();
    normalizeMathListenButtons_();
}

function scheduleMathUiNormalize_() {
    if (mathUiNormalizeRaf_) cancelAnimationFrame(mathUiNormalizeRaf_);
    mathUiNormalizeRaf_ = requestAnimationFrame(() => {
        mathUiNormalizeRaf_ = 0;
        normalizeMathUi_();
    });
}

function installMathUiObserver_() {
    mathUiObserver_?.disconnect?.();
    if (!mathModuleRoot_) return;
    mathUiObserver_ = new MutationObserver(scheduleMathUiNormalize_);
    mathUiObserver_.observe(mathModuleRoot_, {childList:true, subtree:true});
    normalizeMathUi_();
}

function mountMathRuntime_() {
    if(!mathModuleCtx_?.host) throw new Error('MATH_MODULE_HOST_MISSING');
    ensureMathStyles_();
    mathModuleCtx_.host.innerHTML=`<div id="${MATH_MODULE_RUNTIME_ID_}">${MATH_RUNTIME_HTML_}</div>`;
    mathModuleRoot_=document.getElementById(MATH_MODULE_RUNTIME_ID_);
    syncClass2MathUser_(); resetStars(); installScoreObserver_(); installMathUiObserver_(); primeMathAudio_(); mathModuleMounted_=true;
}

